INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (180, 'playground_listar', 'Playground: lista estudos ativos do usuario — param usuario.', 'SQL', 'SELECT ID, NOME, SHARE_TOKEN, TASK_ID, CRIADO_EM, ATUALIZADO_EM, (HTML IS NOT NULL AND HTML <> '''') AS TEM_HTML FROM PLAYGROUND WHERE USUARIO = ''{{usuario}}'' AND ATIVO = ''true'' ORDER BY ATUALIZADO_EM DESC LIMIT 100', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
